package fonts

import "github.com/gabriel/ascii-banner-studio/internal/core/domain"

// NewIsometricFont es la fuente FIGlet 'isometric1' (nombre visible 'Isometric').
// Generada desde pyfiglet para ampliar la variedad de ASCII.
// Altura: 11. Incluye 54 glyphs ASCII imprimibles (32..126) donde la fuente original los define;
// los ausentes usan el fallback '?' del motor sin panics.
func NewIsometricFont() domain.Font {
	return domain.Font{
		ID:         "isometric",
		Name:       "Isometric",
		Height:     11,
		Characters: buildFigletCharacters(figlet_isometricPatterns),
		Fallback:   '?',
	}
}

